class Trie {
    private static final class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isEnd = false;
    }

    private final TrieNode root;

    public Trie() {
        root = new TrieNode();
    }

    public void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        node.isEnd = true;
    }

    public boolean search(String word) {
        TrieNode node = find(word);
        return node != null && node.isEnd;
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }

    private TrieNode find(String value) {
        TrieNode node = root;
        for (char c : value.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                return null;
            }
            node = node.children[idx];
        }
        return node;
    }
}

import java.util.*;

class Trie {
    private static final class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        boolean isEnd = false;
    }

    private final TrieNode root;

    public Trie() {
        root = new TrieNode();
    }

    public void insert(String word) {
        TrieNode node = root;
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            node = node.children.computeIfAbsent(c, key -> new TrieNode());
        }
        node.isEnd = true;
    }

    public boolean search(String word) {
        TrieNode node = find(word);
        return node != null && node.isEnd;
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }

    private TrieNode find(String value) {
        TrieNode node = root;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            node = node.children.get(c);
            if (node == null) {
                return null;
            }
        }
        return node;
    }
}

class Trie {
    private static final class Node {
        char c;
        Node left;
        Node mid;
        Node right;
        boolean isEnd;

        Node(char c) {
            this.c = c;
        }
    }

    private Node root;

    public Trie() {
    }

    public void insert(String word) {
        root = insert(root, word, 0);
    }

    private Node insert(Node node, String word, int index) {
        char c = word.charAt(index);
        if (node == null) {
            node = new Node(c);
        }

        if (c < node.c) {
            node.left = insert(node.left, word, index);
        } else if (c > node.c) {
            node.right = insert(node.right, word, index);
        } else if (index + 1 == word.length()) {
            node.isEnd = true;
        } else {
            node.mid = insert(node.mid, word, index + 1);
        }
        return node;
    }

    public boolean search(String word) {
        Node node = find(word);
        return node != null && node.isEnd;
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }

    private Node find(String value) {
        Node node = root;
        int index = 0;
        while (node != null) {
            char c = value.charAt(index);
            if (c < node.c) {
                node = node.left;
            } else if (c > node.c) {
                node = node.right;
            } else if (index + 1 == value.length()) {
                return node;
            } else {
                index++;
                node = node.mid;
            }
        }
        return null;
    }
}

import java.util.*;

class Trie {
    private final Set<String> words = new HashSet<>();
    private final Set<String> prefixes = new HashSet<>();

    public Trie() {
    }

    public void insert(String word) {
        words.add(word);
        for (int i = 1; i <= word.length(); i++) {
            prefixes.add(word.substring(0, i));
        }
    }

    public boolean search(String word) {
        return words.contains(word);
    }

    public boolean startsWith(String prefix) {
        return prefixes.contains(prefix);
    }
}
